-- Developments gaps 2: site assessments, stock, team schedule, insurance & regulations, actual rent for build-to-rent (applied via Supabase; same RLS pattern as dev-gaps-build.sql)
create table if not exists dev_site_assessments (id uuid primary key default gen_random_uuid(), user_id uuid not null, created_at timestamptz default now(), project_id uuid references dev_projects(id) on delete set null, site text not null, kind text default 'Site visit', assessor text, assessed_date date, status text default 'Planned', findings text);
create table if not exists dev_stock (id uuid primary key default gen_random_uuid(), user_id uuid not null, created_at timestamptz default now(), project_id uuid references dev_projects(id) on delete cascade, material text not null, location text, unit text, qty_in numeric default 0, qty_used numeric default 0, reorder_level numeric, notes text);
create table if not exists dev_schedules (id uuid primary key default gen_random_uuid(), user_id uuid not null, created_at timestamptz default now(), project_id uuid references dev_projects(id) on delete cascade, person_name text not null, role text, work_date date, start_time text, end_time text, task text, notes text);
create table if not exists dev_insurance (id uuid primary key default gen_random_uuid(), user_id uuid not null, created_at timestamptz default now(), project_id uuid references dev_projects(id) on delete cascade, kind text default 'Construction insurance', title text not null, provider text, reference text, cover_amount numeric, start_date date, expiry_date date, status text default 'Active', notes text);
alter table dev_btr add column if not exists actual_rent_monthly numeric;
